  // Restrict fallbacks to flipping to the opposite side along the relevant axis.
  if (strategy === 'opposite-side') {
    switch (side) {
      case 'outside-top':
      case 'outside-bottom':
      case 'inside-top':
      case 'inside-bottom':
        return 'flip-block'
      case 'outside-left':
      case 'outside-right':
      case 'inside-left':
      case 'inside-right':
        return 'flip-inline'
      default:
        return undefined
    }
  }

  // 'default': don't write an inline `position-try-fallbacks`, so the
  // stylesheet-defined fallback list on `.AnchoredOverlay` takes effect.
  return undefined
}

function assignRef<T>(
  ref: React.MutableRefObject<T | null> | ((instance: T | null) => void) | null | undefined,
  value: T | null,
) {
  if (typeof ref === 'function') {
    ref(value)
  } else if (ref) {
    ref.current = value
  }
}

