              </ActionList.Group>
            </ActionList>
          </div>
        </PageLayout.Pane>
        <PageLayout.Content
          hidden={{
            narrow: currentHash.includes('#index'),
            regular: false,
            wide: false,
          }}
        >
          {!currentHash || currentHash.includes('#index') || currentHash.includes('#fruits')
            ? getFilteredItems('fruits').map(item => <Placeholder key={item.name} height={48} label={item.name} />)
            : null}
