    }
    parentElement.appendChild(element)
    onMountRef.current?.()

    return () => {
      parentElement.removeChild(element)
    }
  }, [element, isClientRender, _containerName, portalContainerName])

  return element && isClientRender ? createPortal(children, element) : null
}

