                {label.name}
                <ActionList.Description variant="block">{label.description}</ActionList.Description>
              </ActionList.Item>
            ))}
          </ActionList>
        )}

        <SelectPanel.Footer>
          <SelectPanel.SecondaryAction variant="button">Edit labels</SelectPanel.SecondaryAction>
        </SelectPanel.Footer>
      </SelectPanel>
    </>
